inline fs::path uninstallTarget(){
    auto folder=executable().parent_path(),receipt=folder/L".sma-install.json";
    if(fs::exists(receipt)){auto target=full(fs::path(wide(readjson(receipt).get("InstallRoot").str())));if(!fs::is_regular_file(target/L"SekiModAssistant.exe")||!fs::is_regular_file(target/L"Uninstall.exe"))throw Fault("installerInvalid");return target;}
    if(lower(executable().filename().wstring())==L"uninstall.exe"&&fs::is_regular_file(folder/L"SekiModAssistant.exe"))return folder;
    throw Fault("installerInvalid");
}
