        stub=sizes[0];uint64_t total=40;for(auto n:sizes){if(n>length-total)throw Fault("installerInvalid");total+=n;}if(total!=length)throw Fault("installerInvalid");space(folder,sizes[1]+sizes[2]+sizes[3]);in.seekg(std::streamoff(stub));seven=folder/L"7z.exe";copyRange(in,seven,sizes[1]);copyRange(in,folder/L"7z.dll",sizes[2]);zip=folder/L"payload.zip";copyRange(in,zip,sizes[3]);
